from typing import List

from rosterkit.models import Student

def format_rows(groups: List[List[Student]]) -> List[str]:
    rows = []
    for number, group in enumerate(groups, 1):
        names = " | ".join(
            item.display_name for item in group
        )
        rows.append(f"Row {number}: {names}")
    return rows

def split_rows(
    ordered: List[Student], per_row: int
) -> List[List[Student]]:
    return [
        ordered[start : start + per_row]
        for start in range(0, len(ordered), per_row)
    ]

def seat_rows(
    roster: List[Student], per_row: int
) -> List[str]:
    """One line per row, students sorted by last name."""
    if per_row <= 0 or not roster:
        raise ValueError("bad roster or seats per row")
    people = sorted(roster, key=lambda item: item.last_name)
    return format_rows(split_rows(people, per_row))

