import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student

class SeatRowsTests(unittest.TestCase):
    def setUp(self):
        self.roster = [
            Student("1", "Thistle", "Bram", "A"),
            Student("2", "Dunmere", "Piet", "A"),
            Student("3", "Halloway", "Juno", "A"),
        ]

    def test_sorted_by_last_name_then_chunked(self):
        rows = seat_rows(self.roster, 2)
        self.assertEqual(
            rows,
            [
                "Row 1: Dunmere, Piet | Halloway, Juno",
                "Row 2: Thistle, Bram",
            ],
        )

    def test_one_row_holds_everyone(self):
        expected = (
            "Row 1: Dunmere, Piet | Halloway, Juno | "
            "Thistle, Bram"
        )
        rows = seat_rows(self.roster, 3)
        self.assertEqual(rows, [expected])

    def test_zero_seats_raises(self):
        with self.assertRaises(ValueError):
            seat_rows(self.roster, 0)

    def test_negative_seats_raises(self):
        with self.assertRaises(ValueError):
            seat_rows(self.roster, -1)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seat_rows([], 2)
